namespace sv_931a9ceb30f14ddc9bf7aca846bb7573;

public record TaskItem(int Id, string Title, string Assignee, string Priority, DateTime DueDate, string Status);

public interface ITaskService
{
    Task<List<TaskItem>> GetAllTasksAsync();
    Task<TaskItem> CreateTaskAsync(string title, string assignee, string priority, DateTime dueDate);
    Task UpdateTaskStatusAsync(int taskId, string newStatus);
}

.board-stats {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.board-stats .stat {
    font-weight: 600;
    font-size: 0.9rem;
}

.board-stats .stat-overdue {
    color: #dc3545;
}

.board-search {
    margin-bottom: 1rem;
}

.board-search input {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    font-size: 0.9rem;
}

.kanban-board {
    display: flex;
    gap: 1rem;
    overflow-x: auto;
    padding-bottom: 1rem;
}

.kanban-column {
    flex: 1;
    min-width: 280px;
    background: #f1f3f5;
    border-radius: 8px;
    padding: 1rem;
    display: flex;
    flex-direction: column;
}

.column-header h3 {
    margin: 0 0 0.75rem;
    font-size: 1rem;
}

.column-body {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.75rem;
}

.task-card .task-title {
    margin: 0 0 0.25rem;
    font-size: 0.95rem;
}

.task-card .task-assignee {
    margin: 0 0 0.5rem;
    font-size: 0.8rem;
    color: #6c757d;
}

.task-card .task-due-date {
    font-size: 0.8rem;
    color: #6c757d;
    margin-left: 0.5rem;
}

.priority-badge {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 600;
}

.priority-high {
    background: #f8d7da;
    color: #842029;
}

.priority-medium {
    background: #fff3cd;
    color: #664d03;
}

.priority-low {
    background: #d1e7dd;
    color: #0f5132;
}

.task-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.5rem;
}

.btn-move {
    padding: 0.25rem 0.5rem;
    font-size: 0.75rem;
    border: 1px solid #dee2e6;
    background: #fff;
    border-radius: 4px;
    cursor: pointer;
}

.btn-move:hover {
    background: #e9ecef;
}

.column-footer {
    margin-top: 0.75rem;
}

.btn-add-task {
    width: 100%;
    padding: 0.5rem;
    border: 1px dashed #adb5bd;
    background: transparent;
    border-radius: 6px;
    cursor: pointer;
    color: #6c757d;
}

.btn-add-task:hover {
    background: #e9ecef;
}

.add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    background: #fff;
    padding: 0.75rem;
    border-radius: 6px;
    border: 1px solid #dee2e6;
}

.add-task-form input,
.add-task-form select {
    padding: 0.4rem 0.5rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    font-size: 0.85rem;
}

.form-actions {
    display: flex;
    gap: 0.5rem;
}

.btn-save {
    padding: 0.4rem 0.75rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.btn-cancel {
    padding: 0.4rem 0.75rem;
    background: #6c757d;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.loading {
    color: #6c757d;
    font-style: italic;
}

.error {
    color: #dc3545;
    font-weight: 600;
}

